#include<bits/stdc++.h>

using namespace std;

int main(){
  string s;
  cin >> s;
  int l=s.size();
  int p=0,res=0;
  while(p<l){
    res++;
    if((p+1)<l && s[p]=='0' && s[p+1]=='0'){p+=2;}
    else{p++;}
  }
  cout << res << "\n";
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

int main(){
  string s;
  cin >> s;
  int l=s.size();
  int z=0,res=0;
  for(auto &nx : s){
    if(nx=='0'){
      z++;
    }
    else{
      res+=(z+1)/2;
      z=0;
      res++;
    }
  }
  res+=(z+1)/2;
  cout << res << "\n";
  return 0;
}
